begin;
create extension if not exists pgtap with schema public;
select plan(21);
select has_table('public','cycle_count_round_item_attestations','blind missing-item attestations are durable');
select has_function('public','attest_cycle_count_item_absence',array['uuid','uuid','text','text','text','uuid'],'blind absence RPC exists');
select col_is_fk('public','cycle_count_round_results','item_attestation_id','result references absence evidence');
select has_function('public','submit_cycle_count_round',array['uuid','uuid','boolean'],'explicit round submit exists');
select has_function('public','list_cycle_count_round_results',array['uuid','uuid','uuid'],'governed result history exists');
select has_function('public','get_cycle_count_round_progress',array['uuid','uuid'],'round progress exists');
select has_view('public','cycle_count_latest_round_results','latest-result authority has a view');
select view_owner_is('public','cycle_count_latest_round_results',current_user,'latest-result view has expected owner');
select is((select 'security_invoker=true'=any(reloptions) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='cycle_count_latest_round_results'),true,'latest-result view is security invoker');
select function_privs_are('public','submit_cycle_count_round',array['uuid','uuid','boolean'],'authenticated',array['EXECUTE'],'authenticated uses governed submit');
select function_privs_are('public','submit_cycle_count_for_review',array['uuid','uuid','boolean'],'authenticated',array[]::text[],'legacy all-round submit is revoked');
select function_privs_are('public','list_cycle_count_round_results',array['uuid','uuid','uuid'],'authenticated',array['EXECUTE'],'authenticated uses governed history RPC');
select function_privs_are('public','get_cycle_count_round_progress',array['uuid','uuid'],'authenticated',array['EXECUTE'],'authenticated uses governed progress RPC');
select is((select prosecdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='submit_cycle_count_round'),true,'submit is SECURITY DEFINER');
select is((select proconfig @> array['search_path=""'] from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='submit_cycle_count_round'),true,'submit pins search path');
select col_is_fk('public','cycle_count_round_results','item_observation_id','item result references evidence');
select col_is_fk('public','cycle_count_round_results','lot_observation_id','lot result references evidence');
select has_index('public','cycle_count_round_results','cycle_count_round_results_item_once','one item result per round');
select has_index('public','cycle_count_round_results','cycle_count_round_results_lot_once','one lot result per round');
select is((select count(*)::int from information_schema.role_table_grants where table_schema='public' and table_name='cycle_count_latest_round_results' and grantee in ('authenticated','anon','PUBLIC')),0,'latest results have no direct client grant');
select is((select count(*)::int from information_schema.routine_privileges where grantee='anon' and routine_schema='public' and routine_name in ('submit_cycle_count_round','list_cycle_count_round_results','get_cycle_count_round_progress')),0,'anon cannot use governed round reads or submit');
select * from finish();
rollback;
